"""Quoted component composition and inspectable measure evidence."""
SCRIPT=r'''
function renderMeasure(parent,r,fetchJSON){
 const N=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e},pretty=s=>s.replaceAll('_',' '),detail=(title,obj)=>{const d=N('details');d.append(N('summary',title),N('pre',JSON.stringify(obj,null,2)));return d},percent=v=>v===null?'undefined':(100*v).toFixed(2)+'%';
 parent.append(N('h2',r.definition.title),N('p',r.patients_evaluated.toLocaleString()+' synthetic patients · snapshot '+r.snapshot.as_of),N('h3','Known numerator '+r.counts.known_numerator+' / known denominator '+r.counts.known_denominator),N('p',r.counts.unresolved_measure_patients+' patients have unresolved measure inputs.'),N('h3','Complete documentary rate: '+percent(r.rate)),N('p',pretty(r.rate_status)));
 const b=r.sensitivity_bounds;parent.append(N('h3','Logical sensitivity: '+percent(b.minimum)+' to '+percent(b.maximum)),N('p','These bounds describe possible completed input values, conditional on a nonempty denominator. They are not probabilities, confidence intervals or predicted performance.'),N('p',b.zero_denominator_possible?'A zero denominator is also possible.':'The denominator stays nonzero in these logical completions.'),N('p','Mapping reviews pending: '+(r.unreviewed_component_roles.join(', ')||'none')+'. Descriptive components not applied: '+(r.not_applied_components.join(', ')||'none')+'.'));
 const form=N('form'),label=N('label','Inspect measure evidence for a synthetic patient'),input=N('input');input.required=true;input.maxLength=150;label.append(input);const go=N('button','Inspect all measure components');go.type='submit';form.append(label,go);const patient=N('div');
 form.onsubmit=async e=>{e.preventDefault();go.disabled=true;try{const d=await fetchJSON('/api/stack/measure?id='+r.id+'&patient='+encodeURIComponent(input.value)),p=d.patient;if(p.patient_id!==input.value)throw Error('Patient mismatch');patient.replaceChildren(N('h3',p.patient_id+' · '+pretty(p.status)));for(const [role,c] of Object.entries(p.components)){patient.append(N('h3',pretty(role)+' · '+(c.value===null?'unresolved':c.value)),N('p',pretty(c.status)));if(c.reason)patient.append(N('p',c.reason));const source=d.source_receipts[c.package];if(source)for(const i of Object.values(source.inputs))patient.append(N('blockquote',i.quote.quote),N('p',i.label+': '+(i.value===null?'unresolved':i.value)))}patient.append(detail('Exact component sources, review states and mathematical possibilities',d))}catch(err){patient.replaceChildren(N('p',err.message))}finally{go.disabled=false}};
 parent.append(form,patient,detail('Complete measurement receipt and limitations',r));
}
'''


def page():
 from .program_document_workbench import HTML
 style=HTML[HTML.index('<style>'):HTML.index('</style>')+8].replace('</style>','[hidden]{display:none!important}</style>')
 return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agere · Measure composition</title>'+style+BODY+'<script>'+SCRIPT+FORM+'</script></html>'

BODY='''<main><nav><a class="brand" href="/stack">AGERE</a><a href="/program-documents">Quoted specifications</a><a href="/programs">Review work</a></nav><div class="eyebrow">EVIDENCE → COMPONENTS → MEASUREMENT</div><h1>Every number.<br><em>Every dependency.</em></h1><p>Compose versioned documentary criteria across the complete synthetic population. See the denominator, numerator, exclusions and attribution together, with missing inputs kept visible.</p><div id="status" role="status" aria-live="polite">Loading quoted components…</div><div class="layout"><section class="panel"><form id="form"><label>Measure title<input id="title" maxlength="300" value="Synthetic documentary measure" required></label><div id="components"></div><label>Optional separate review program<select id="program"><option value="">Measure only</option></select></label><button type="submit">Compose full synthetic population</button></form><p>Optional components start unbound. Choosing “not applied” explicitly produces a descriptive statistic, not a certified payer measure. Component roles must match their immutable packages.</p></section><section id="results" class="panel"><h2>The full evidence path</h2><p>Select quoted denominator and numerator specifications. An unknown exclusion or attribution remains unknown.</p></section></div><footer>All patients are synthetic. These are snapshot patient counts, not certified quality measures, clinical eligibility, actual attribution, payment or savings. No model calls or patient actions are triggered by this form.</footer></main>'''
FORM=r'''
const $=id=>document.getElementById(id),N=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e},roles=['denominator','numerator','exclusion','attribution'];let controls={};
async function api(url,body){const r=await fetch(url,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const text=await r.text();let d;try{d=JSON.parse(text)}catch{throw Error('Unable to read response ('+r.status+')')}if(!r.ok)throw Error(d.error||'Request failed');return d}
async function load(){const d=await api('/api/stack/program-documents');for(const role of roles){const label=N('label',role[0].toUpperCase()+role.slice(1)),select=N('select');if(['exclusion','attribution'].includes(role)){for(const [v,t] of [['unbound','Unbound — preserve unknown'],['not_applied','Not applied — descriptive statistic']]){const o=N('option',t);o.value=v;select.append(o)}}else{const o=N('option','Select quoted '+role);o.value='';select.required=true;select.append(o)}for(const p of d.packages.filter(p=>p.role===role)){const o=N('option',p.purpose+' · v'+p.version);o.value=p.id;select.append(o)}label.append(select);const reasonLabel=N('label','Reason if '+role+' is unbound or not applied'),reason=N('input');reason.maxLength=2000;reason.value='No quoted '+role+' specification is bound.';reasonLabel.append(reason);reasonLabel.hidden=!['unbound','not_applied'].includes(select.value);select.onchange=()=>reasonLabel.hidden=!['unbound','not_applied'].includes(select.value);$('components').append(label,reasonLabel);controls[role]={select,reason}}
const work=await api('/api/stack/work');for(const p of work.programs){const o=N('option',p.name);o.value=p.id;$('program').append(o)}$('status').textContent='Quoted components loaded. All mappings retain their recorded review state.'}
$('form').onsubmit=async e=>{e.preventDefault();const button=$('form').querySelector('button');button.disabled=true;try{const components={};for(const [role,c] of Object.entries(controls)){if(!c.select.value)throw Error('Select '+role);components[role]=['unbound','not_applied'].includes(c.select.value)?{[c.select.value]:c.reason.value}:{package:c.select.value}}const nodes=[{id:'population',operation:'cohort',inputs:[],parameters:{specification:{all:[],any:[],exclude:[]}},purpose:'Complete observed synthetic population'},{id:'measure',operation:'measure_review',inputs:['population'],parameters:{title:$('title').value,components},purpose:'Compose quoted documentary components, preserving missing inputs'}];if($('program').value)nodes.push({id:'work',operation:'worklist',inputs:['population','measure'],parameters:{program:$('program').value},purpose:'Attach measure context to a separate clinical review'});$('status').textContent='Composing every patient’s source-linked components…';const d=await api('/api/stack/execute-plan',{interpretation:'Documentary measure composition; eligibility and payment remain unverified.',coverage:'supported_observation',unmet_requirements:[],nodes}),r=d.results.find(x=>x.node.operation==='measure_review').result;$('results').replaceChildren();renderMeasure($('results'),r,api);const w=d.results.find(x=>x.node.operation==='worklist')?.result;if(w)$('results').append(N('h3','Separate clinical review'),N('p',w.counts.selected+' assessed · '+w.counts.candidates+' review candidates · measure context retained'));$('status').textContent='Full population composed locally. No paid calls, work events or clinical actions.'}catch(err){$('status').textContent=err.message}finally{button.disabled=false}};load().catch(err=>$('status').textContent=err.message);
'''
